/* AutoGrowth OS reconstructed navigation and functional demo, no CHUI mascot/chatbot. */
const navigation = [
 {name:'HOME',icon:'▦',items:[['dashboard','Command Center']]},
 {name:'SALES',icon:'♧',items:[['leads','Lead CRM'],['inbox','Conversation Inbox'],['assignment','Advisor Assignment'],['tasks','Follow-ups & Tasks'],['documents','Documents & Agreements'],['quotes','Sales Quote Tools'],['pipeline','Sales Pipeline']]},
 {name:'AI INTELLIGENCE',icon:'✧',items:[['recommendations','AI Growth Recommendations'],['summaries','Conversation Summaries'],['opportunities','Detected Opportunities'],['alerts','Missing Data Alerts']]},
 {name:'CAMPAIGNS',icon:'◈',items:[['campaigns','Campaign Intelligence'],['channels','Channel Metrics'],['reports','Export Reports']]},
 {name:'CLIENT KNOWLEDGE',icon:'▤',items:[['knowledge','Knowledge Base'],['inventory','Models & Inventory'],['audiences','Audience Insights']]},
 {name:'POST-SALES & PARTS',icon:'⚒',items:[['service','Service Dashboard'],['appointments','Service Appointments'],['parts','Parts & Accessories']]},
 {name:'SETTINGS',icon:'⚙',items:[['agent','Customer-Facing Agent'],['integrations','Connected Channels'],['users','Users & Roles'],['system','System Status'],['clientsettings','Client Settings'],['clients','Clients']]}
];
Object.assign(headings,{assignment:['Advisor Assignment','Distribución comercial de oportunidades'],tasks:['Follow-ups & Tasks','Agenda de acciones y vencimientos'],documents:['Documents & Agreements','Archivos comerciales y documentación'],recommendations:['AI Growth Recommendations','Diagnósticos de campañas y oportunidades'],summaries:['Conversation Summaries','Resumen de conversaciones del CRM'],opportunities:['Detected Opportunities','Señales de crecimiento y conversiones'],alerts:['Missing Data Alerts','Calidad y completitud de datos'],channels:['Channel Metrics','Comparativa de canales publicitarios'],knowledge:['Knowledge Base','Información comercial centralizada'],inventory:['Models & Inventory','Catálogo y disponibilidad de vehículos'],audiences:['Audience Insights','Segmentos y perfiles de prospectos'],appointments:['Service Appointments','Agenda de taller'],parts:['Parts & Accessories','Consultas y oportunidades de repuestos'],agent:['Customer-Facing Agent','Configuración de agentes externos'],users:['Users & Roles','Accesos y permisos de demostración'],system:['System Status','Salud de integraciones'],clientsettings:['Client Settings','Preferencias por concesionario'],clients:['Clients','Organizaciones del workspace']});
const original={dashboard,leads:leadsPage,pipeline,inbox,campaigns,quotes,reports,service,integrations};
let openGroup='HOME',quoteType='used',campaignChannel='All',recCampaign='all',dateRange='2026-08-01|2026-08-12';
const records=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('ag_'+key))||fallback}catch{return fallback}};
const put=(key,val)=>localStorage.setItem('ag_'+key,JSON.stringify(val));
let tasks=records('tasks',[{id:1,title:'Contactar a María González',owner:'Lucía Torres',due:'2026-11-07',status:'Pendiente',client:'cardys_fiat'},{id:2,title:'Enviar propuesta Compass',owner:'Martín Díaz',due:'2026-11-09',status:'En curso',client:'overland_motors'}]);
let docs=records('docs',[{id:1,title:'Lista de precios FIAT',type:'Cotizador',client:'cardys_fiat',date:'2026-06-01',filename:'LISTA PRECIOS JUNIO fiat 2026.xlsx'},{id:2,title:'Condiciones de financiación',type:'Financiación',client:'overland_motors',date:'2026-08-12',filename:'Condiciones-demo.pdf'}]);
let knowledge=records('knowledge',[{id:1,title:'Proceso de adjudicación',category:'Financiación',body:'Confirmar condiciones vigentes de adjudicación, documentación y aprobación con el concesionario.'},{id:2,title:'Tratamiento de leads nuevos',category:'Ventas',body:'Asignar responsable, registrar primer contacto y seguimiento; no dejar leads sin dueño.'}]);
let people=records('users',[{id:1,name:'Guillermina Dana',email:'demo-admin@autogrowth.local',role:'Super Admin',client:'all'},{id:2,name:'Lucía Torres',email:'lucia@demo.local',role:'Sales Advisor',client:'cardys_fiat'},{id:3,name:'Martín Díaz',email:'martin@demo.local',role:'Sales Advisor',client:'overland_motors'}]);
let appointments=records('appointments',[{id:1,customer:'Laura Fernández',model:'Fiat Cronos',date:'2026-11-10',service:'Service programado',status:'Confirmado',client:'cardys_fiat'}]);
const campaignLedger=[{id:1,name:'CP_WHATS_VENTA CONVECIONAL_MAYO',client:'cardys_fiat',channel:'Meta Ads',objective:'OUTCOME_LEADS',spend:5897.36,leads:2,ctr:2.28,impressions:1755,status:'Active',booked:0,closed:0,responded:0},{id:2,name:'SECUENCIA_PDA_MAYO- JUNIO',client:'cardys_fiat',channel:'Meta Ads',objective:'OUTCOME_LEADS',spend:4937.64,leads:1,ctr:1.66,impressions:1214,status:'Active',booked:0,closed:0,responded:0},{id:3,name:'Cardys_Leads_PlanDeAhorro_FEB',client:'cardys_fiat',channel:'Meta Ads',objective:'LEAD_GENERATION',spend:0,leads:0,ctr:0,impressions:0,status:'Paused',booked:0,closed:0,responded:0},{id:4,name:'2020.04.09 Cardys',client:'cardys_fiat',channel:'Meta Ads',objective:'POST_ENGAGEMENT',spend:0,leads:0,ctr:0,impressions:0,status:'Paused',booked:0,closed:0,responded:0},{id:5,name:'Compass · Captación',client:'overland_motors',channel:'Meta Ads',objective:'OUTCOME_LEADS',spend:5400,leads:4,ctr:1.94,impressions:3800,status:'Active',booked:1,closed:0,responded:2},{id:6,name:'RAM Rampage · Search',client:'overland_motors',channel:'Google Ads',objective:'LEAD_GENERATION',spend:3800,leads:3,ctr:3.4,impressions:2700,status:'Active',booked:0,closed:0,responded:2}];
const selectedCampaigns=()=>campaignLedger.filter(c=>{const [from,to]=dateRange.split('|');const when=c.date||'2026-08-12';return (selected==='all'||c.client===selected)&&(campaignChannel==='All'||c.channel===campaignChannel)&&when>=from&&when<=to});
const fmtUSD=n=>'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function newNav(){document.querySelector('.brand').innerHTML='<div class="brand-mark logo-mark" aria-label="AutoGrowth logo"></div><div><strong>AutoGrowth OS</strong><small>Super Admin · DEMO</small></div>';document.getElementById('nav').innerHTML=navigation.map(g=>`<div class="nav-group ${openGroup===g.name?'open':''}"><button class="nav-group-head" onclick="toggleGroup('${g.name}')"><span class="left"><span class="ico">${g.icon}</span><span>${g.name}</span></span><span class="arrow">⌄</span></button><div class="subnav ${openGroup===g.name?'':'hidden'}">${g.items.map(([p,name])=>`<button data-page="${p}" class="${page===p?'active':''}" onclick="setPage('${p}')"><span class="txt">${name}</span></button>`).join('')}</div></div>`).join('')}
function toggleGroup(name){openGroup=openGroup===name?'':name;newNav()}
setPage=function(p){page=p;let group=navigation.find(g=>g.items.some(i=>i[0]===p));if(group)openGroup=group.name;document.getElementById('crumb').textContent=headings[p]?.[0]||'AutoGrowth OS';render();newNav();window.scrollTo(0,0)};
const topbarElement=document.querySelector('.topbar');topbarElement.innerHTML=`<div class="breadcrumbs" id="crumb">Command Center</div><div class="top-actions"><span class="pill" style="color:#ffca36">✧ DEMO</span><select class="field" id="topClient" onchange="selected=this.value;render()"><option value="all">Todos los clientes</option><option value="cardys_fiat">Cardys · Fiat</option><option value="overland_motors">Overland Motors</option></select><select class="field" aria-label="Rango temporal" onchange="dateRange=this.value;render()"><option value="2026-08-01|2026-08-12">Ago 1 — Ago 12 · 2026</option><option value="2026-11-01|2026-11-06">Nov 1 — Nov 6 · 2026</option></select><div class="avatar">GD</div></div>`;
document.querySelector('.floating')?.remove();document.querySelector('.chui')?.remove();
const button=(txt,fn,cls='secondary')=>`<button class="btn ${cls}" onclick="${fn}">${txt}</button>`;
function originalDashboard(){let s=subset(),sp=selectedCampaigns().reduce((x,c)=>x+c.spend,0),count=selectedCampaigns().reduce((x,c)=>x+c.leads,0),cpl=count?sp/count:0;return shell(`<div class="notice">Snapshot ilustrativo del diseño original (agosto 2026). No son métricas actuales ni sincronización activa.</div><div class="stats"><div class="stat"><span class="label">Total spent</span><div class="value">${fmtUSD(sp)}</div><span class="muted">Campañas del snapshot</span><hr><span class="mini">✧ Métricas de demostración</span></div><div class="stat"><span class="label">Leads generated</span><div class="value">${count}</div><span class="muted">Meta / Google Ads</span><hr><span class="mini">✧ Por campaña y cliente</span></div><div class="stat"><span class="label">Cost per lead</span><div class="value">${fmtUSD(cpl)}</div><span class="muted">CPL del snapshot</span><hr><span class="mini">✧ Compará eficiencia</span></div><div class="stat"><span class="label">Appointments booked</span><div class="value">${selectedCampaigns().reduce((x,c)=>x+c.booked,0)}</div><span class="muted">Seguimiento comercial</span><hr><span class="mini">✧ CRM y etapas</span></div></div><div class="grid"><section class="panel"><div class="panel-head"><h2>Lead performance</h2><span class="muted">30 DAY TREND · ilustrativo</span></div><div class="chart-wrap"><div class="chart">${[78,63,85,55,71,94,66].map((v,i)=>`<div class="bar-group"><div class="bar" style="height:${v}%"></div><label>${['L','M','M','J','V','S','D'][i]}</label></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>AI Growth Recommendations</h2><span class="tag gold">PRIORIDAD</span></div><h2 style="margin:20px 0">Los leads que no se registran en CRM no pueden medirse hasta el cierre.</h2><p class="muted">Conectá el resultado de campañas con contacto, reserva y venta.</p>${button('Ver análisis →',"setPage('recommendations')")}</section></div><section class="panel"><div class="panel-head"><h2>Lead CRM</h2>${button('Ver todos →',"setPage('leads')")}</div>${leadTable(s.slice(0,5))}</section>`)}
function intelligence(){let arr=selectedCampaigns().filter(c=>recCampaign==='all'||String(c.id)===recCampaign);return shell(`<div class="recs-toolbar"><select class="field" id="recSelect" onchange="recCampaign=this.value;render()"><option value="all">All campaigns</option>${selectedCampaigns().map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><div class="metrics-actions"><span class="tag">RULES ENGINE · DEMO</span>${button('⌘ View JSON','viewAnalysisJson()')}${button('✧ Run analysis','runAnalysis()','yellow')}</div></div><div class="eyebrow" style="margin:21px 0">THE INTELLIGENCE LAYER</div><h1>Turn performance signals into action.</h1><p class="sub" style="max-width:920px;margin-bottom:28px">Cada análisis conecta eficiencia publicitaria con contacto, turnos y resultados comerciales, y propone próximos pasos para Marketing y Ventas.</p>${arr.map(c=>analysisCard(c)).join('')||'<div class="empty-state">No hay campañas en este filtro.</div>'}`)}
function analysisCard(c){let cpl=c.leads?c.spend/c.leads:0,issue=!c.leads?'No se registraron leads en el período.':!c.responded?'No hay contactos registrados en CRM para los leads atribuidos.':'La conversión de contacto a turno puede mejorarse.';let priority=c.leads&&!c.responded?'HIGH':'MEDIUM';return `<article class="analysis-card"><div class="analysis-top"><div><h2>${esc(c.name)} <span class="tag gold">${priority} PRIORITY</span></h2><div class="muted" style="margin-top:12px">${c.channel} · ${c.objective}</div></div><div class="analysis-metrics"><div><b>${fmtUSD(cpl)}</b><small>CPL</small></div><div><b>${c.ctr}%</b><small>CTR</small></div><div><b>${c.booked}</b><small>BOOKED</small></div><div><b>${c.closed}</b><small>CLOSED</small></div></div></div><div class="diagnosis-grid"><div><h3>▥ Performance diagnosis</h3><p>Inversión ${fmtUSD(c.spend)}, ${c.leads} leads, ${fmtUSD(cpl)} CPL y CTR ${c.ctr}%. ${c.leads?'Evaluar también resultados del CRM para decidir cambios de pauta.':'Revisar segmentación, anuncio y medición antes de incrementar presupuesto.'}</p></div><div><h3>⚠ Main issue detected</h3><p>${issue}</p></div><div><h3>✧ Recommended action</h3><p>${c.leads&&!c.responded?'Registrar cada conversación como lead y asignar asesor, para medir contacto, reserva y cierre.':'Validar origen, responsable y estados; optimizar los canales según calidad y costo por oportunidad.'}</p></div></div><div class="team-actions"><div><b>◈ Marketing team</b><p>Revisar objetivo, creatividad y CPL; no asumir que el problema es la pauta sin revisar el embudo.</p></div><div><b>♧ Sales / advisor team</b><p>Registrar contacto, asignación y resultado por campaña. Ejecutar follow-ups con fecha y dueño.</p></div></div><div class="analysis-foot">Spend ${fmtUSD(c.spend)} · ${c.impressions.toLocaleString()} impressions · ${c.responded}/${c.leads} contacted <span style="float:right">¿Fue útil? <button class="tiny-btn" onclick="feedback(this,'👍')">👍</button> <button class="tiny-btn" onclick="feedback(this,'👎')">👎</button></span></div></article>`}
function feedback(el,s){el.textContent=s+' Guardado';el.disabled=true}
function runAnalysis(){alert('Diagnóstico basado en reglas recalculado con los datos demo. Para análisis generativo real se requiere conectar un proveedor de IA y datos verificados.');render()}
function viewAnalysisJson(){let c=selectedCampaigns().filter(c=>recCampaign==='all'||String(c.id)===recCampaign);showModal('Análisis JSON',`<pre style="white-space:pre-wrap;overflow:auto;max-height:60vh;color:#d8c1ff">${esc(JSON.stringify(c.map(x=>({...x,cpl:x.leads?x.spend/x.leads:0})),null,2))}</pre>`)}
function campaignIntelligence(){let data=selectedCampaigns();return shell(`<div class="notice">Campaign ledger reconstruido desde la captura histórica. Datos de ejemplo, sin conexión a Meta Ads.</div><section class="panel"><div class="panel-head"><h2>Active and recent campaigns</h2><div class="metrics-actions">${button('↓ Export metrics','exportCampaigns()')}${button('↑ Import metrics','openImportMetrics()')}</div></div><div class="controls"><select class="field" onchange="campaignChannel=this.value;render()"><option>All</option><option ${campaignChannel==='Meta Ads'?'selected':''}>Meta Ads</option><option ${campaignChannel==='Google Ads'?'selected':''}>Google Ads</option></select><span class="muted" style="align-self:center">${data.length} campañas</span></div><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Platform</th><th>Spend</th><th>Leads</th><th>CPL</th><th>CTR</th><th>Status</th><th></th></tr></thead><tbody>${data.map(c=>`<tr><td><strong>${esc(c.name)}</strong><div class="mini">${c.objective}</div></td><td><span class="tag">${c.channel}</span></td><td>${fmtUSD(c.spend)}</td><td>${c.leads}</td><td>${fmtUSD(c.leads?c.spend/c.leads:0)}</td><td>${c.ctr}%</td><td>${c.status==='Active'?tag('Activo'):tag('Pausado')}</td><td><button class="tiny-btn" onclick="recCampaign='${c.id}';setPage('recommendations')">Analizar</button></td></tr>`).join('')}</tbody></table></div></section>`)}
function exportCampaigns(){let rows=[['Campaign','Client','Platform','Spend','Leads','CPL','CTR','Status'],...selectedCampaigns().map(c=>[c.name,c.client,c.channel,c.spend,c.leads,c.leads?c.spend/c.leads:0,c.ctr,c.status])];download('campaign-metrics-demo.csv',rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv')}
function openImportMetrics(){showModal('Importar métricas',`<p class="muted">El archivo se verifica localmente. Esta versión no sincroniza cuentas publicitarias ni sobrescribe el snapshot de referencia.</p><input class="field" type="file" accept=".csv" id="metricsFile"><button class="btn" style="margin-top:18px" onclick="inspectMetrics()">Validar archivo</button>`)}
function inspectMetrics(){let f=document.getElementById('metricsFile').files[0];if(!f)return alert('Elegí un CSV');f.text().then(t=>alert('Archivo leído: '+parseCsv(t).length+' filas. Validación local exitosa; importación real de métricas pendiente de conectar esquema y origen.'))}
function channelsPage(){let data=selectedCampaigns(),groups=['Meta Ads','Google Ads','TikTok Ads','LinkedIn Ads'];return shell(`<div class="stats">${groups.map(g=>{let a=data.filter(c=>c.channel===g),sum=a.reduce((v,c)=>v+c.spend,0),n=a.reduce((v,c)=>v+c.leads,0);return `<div class="stat"><span class="label">${g}</span><div class="value">${n}</div><span class="muted">Leads · ${fmtUSD(sum)} spent</span><p class="mini">${a.length?a.length+' campañas demo':'Sin datos importados'}</p></div>`}).join('')}</div><section class="panel"><h2>Efficiency by channel</h2>${groups.map(g=>{let a=data.filter(c=>c.channel===g),n=a.reduce((v,c)=>v+c.leads,0);return `<div style="margin:22px 0"><div class="panel-head"><b>${g}</b><span>${n} leads</span></div><div class="progress"><i style="width:${data.reduce((x,c)=>x+c.leads,0)?n/data.reduce((x,c)=>x+c.leads,0)*100:0}%"></i></div></div>`}).join('')}</section>`)}
function genericTable(title,subtitle,headers,rows,actions=''){return shell(`<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p class="muted">${subtitle}</p></div>${actions}</div><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty-state">No hay registros para esta vista.</div>'}</div></section>`)}
function assignmentPage(){return genericTable('Advisor Assignment','Responsables comerciales y scoring del CRM',['Lead','Cliente','Score','Asesor'],subset().map(l=>[esc(l.name),clientName(l.client),l.score,`<select class="field" onchange="assignLead(${l.id},this.value)">${['Sin asignar','Lucía Torres','Martín Díaz','Federico Ruiz'].map(n=>`<option ${l.owner===n?'selected':''}>${n}</option>`).join('')}</select>`]))}
function assignLead(id,owner){let l=leads.find(x=>x.id===id);if(l){l.owner=owner;save()}}
function tasksPage(){return genericTable('Follow-ups & Tasks','Acciones editables conservadas en este navegador',['Tarea','Asesor','Vencimiento','Estado',''],tasks.filter(t=>selected==='all'||t.client===selected).map(t=>[esc(t.title),esc(t.owner),esc(t.due),`<select class="field" onchange="taskStatus(${t.id},this.value)">${['Pendiente','En curso','Completada'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select>`,`<button class="tiny-btn" onclick="deleteRecord('tasks',${t.id})">Eliminar</button>`]),button('+ Nueva tarea','newTask()'))}
function taskStatus(id,status){tasks.find(x=>x.id===id).status=status;put('tasks',tasks)}
function newTask(){showModal('Nueva tarea',`<form onsubmit="event.preventDefault();tasks.push({id:Date.now(),title:this.elements.namedItem('title').value,owner:this.elements.namedItem('owner').value,due:this.elements.namedItem('due').value,status:'Pendiente',client:this.elements.namedItem('client').value});put('tasks',tasks);closeModal();render()"><label>Título</label><input class="field" name="title" required><label>Responsable</label><select class="field" name="owner"><option>Lucía Torres</option><option>Martín Díaz</option><option>Federico Ruiz</option></select><label>Vencimiento</label><input type="date" class="field" name="due" required><label>Cliente</label><select class="field" name="client"><option value="cardys_fiat">Cardys · FIAT</option><option value="overland_motors">Overland Motors</option></select><button class="btn" style="margin-top:18px">Guardar tarea</button></form>`)}
function documentsPage(){return shell(`<div class="grid"><section class="panel"><div class="panel-head"><h2>Documents & Agreements</h2>${button('+ Añadir documento','addDocument()')}</div>${docs.filter(d=>selected==='all'||d.client===selected).map(d=>`<div class="doc-card"><b>▤ ${esc(d.title)}</b><small>${esc(d.filename)} · ${esc(d.type)} · ${clientName(d.client)}</small><button class="tiny-btn" style="margin-top:10px" onclick="deleteRecord('docs',${d.id})">Quitar registro</button></div>`).join('')}</section><section class="panel"><h2>Biblioteca documental</h2><p class="muted">Listas de precios, convenios, acuerdos, formularios y anexos. Los adjuntos reales requieren almacenamiento seguro antes de producción.</p><div class="upload-target">↑<p>Registrar documento local</p><span class="mini">La demo conserva metadatos, no archivos de clientes.</span></div></section></div>`)}
function addDocument(){showModal('Registrar documento',`<form onsubmit="event.preventDefault();docs.push({id:Date.now(),title:this.elements.namedItem('title').value,filename:this.elements.namedItem('filename').value,type:this.elements.namedItem('type').value,client:this.elements.namedItem('client').value,date:new Date().toISOString().slice(0,10)});put('docs',docs);closeModal();render()"><label>Descripción</label><input class="field" name="title" required><label>Nombre de archivo</label><input class="field" name="filename" placeholder="Precios_Noviembre.xlsx" required><label>Tipo</label><select class="field" name="type"><option>Cotizador</option><option>Financiación</option><option>Acuerdo</option><option>Otro</option></select><label>Cliente</label><select class="field" name="client"><option value="cardys_fiat">Cardys</option><option value="overland_motors">Overland</option></select><button class="btn" style="margin-top:18px">Guardar</button></form>`)}
function deleteRecord(key,id){if(!confirm('¿Eliminar este registro local?'))return;let v=key==='tasks'?tasks:key==='docs'?docs:key==='knowledge'?knowledge:key==='users'?people:appointments;v=v.filter(x=>x.id!==id);if(key==='tasks')tasks=v;if(key==='docs')docs=v;if(key==='knowledge')knowledge=v;if(key==='users')people=v;if(key==='appointments')appointments=v;put(key,v);render()}
function summariesPage(){return genericTable('Conversation Summaries','Las conversaciones disponibles son de demostración',['Contacto','Interés','Resumen',''],convos.map((c,i)=>[esc(c.name),esc(c.model),esc(c.messages.map(m=>m[0]).join(' · ').slice(0,160))+'…',`<button class="tiny-btn" onclick="selectedChat=${i};setPage('inbox')">Abrir</button>`]))}
function opportunitiesPage(){let high=subset().filter(l=>l.score>=80&&l.status!=='Ganado');return shell(`<div class="stats"><div class="stat"><span class="label">High intent leads</span><div class="value">${high.length}</div></div><div class="stat"><span class="label">Unassigned leads</span><div class="value">${subset().filter(l=>l.owner==='Sin asignar').length}</div></div><div class="stat"><span class="label">Negotiations</span><div class="value">${subset().filter(l=>l.status==='Negociación').length}</div></div></div><section class="panel"><div class="panel-head"><h2>Oportunidades prioritarias</h2>${button('Asignar asesores','setPage(\'assignment\')')}</div>${leadTable(high)}</section>`)}
function alertsPage(){let missing=subset().filter(l=>!l.phone||l.model==='Sin definir'||l.owner==='Sin asignar');return shell(`<div class="notice">La calidad del dato define la confiabilidad de los reportes y las recomendaciones.</div><section class="panel"><h2>Alertas de datos incompletos</h2><p class="muted">${missing.length} registros necesitan revisión</p>${leadTable(missing)}</section>`)}
function knowledgePage(){return shell(`<div class="panel-head"><h2>Knowledge Base</h2>${button('+ Agregar conocimiento','addKnowledge()')}</div><div class="campaigns">${knowledge.map(k=>`<div class="campaign"><span class="tag">${esc(k.category)}</span><h3>${esc(k.title)}</h3><p class="muted">${esc(k.body)}</p><button class="tiny-btn" onclick="deleteRecord('knowledge',${k.id})">Eliminar</button></div>`).join('')}</div>`)}
function addKnowledge(){showModal('Añadir artículo',`<form onsubmit="event.preventDefault();knowledge.push({id:Date.now(),title:this.elements.namedItem('title').value,category:this.elements.namedItem('category').value,body:this.elements.namedItem('body').value});put('knowledge',knowledge);closeModal();render()"><label>Título</label><input class="field" required name="title"><label>Categoría</label><select class="field" name="category"><option>Ventas</option><option>Financiación</option><option>Postventa</option><option>General</option></select><label>Contenido</label><textarea class="field" style="width:100%;min-height:125px" required name="body"></textarea><button class="btn" style="margin-top:15px">Guardar artículo</button></form>`)}
function inventoryPage(){let models=[['FIAT','Cronos','Sedán'],['FIAT','Mobi','Hatch'],['FIAT','Pulse','SUV'],['FIAT','Strada','Pickup'],['FIAT','Toro','Pickup'],['Jeep','Renegade','SUV'],['Jeep','Compass','SUV'],['Jeep','Commander','SUV'],['RAM','Rampage','Pickup'],['RAM','Dakota','Pickup']];return genericTable('Models & Inventory','Modelos de referencia; stock y precios no sincronizados',['Marca','Modelo','Segmento','Estado'],models.filter(m=>selected==='all'||(selected==='cardys_fiat'?m[0]==='FIAT':m[0]!=='FIAT')).map(m=>[...m.map(esc),tag('Consultar stock')]))}
function audiencesPage(){let s=subset(),sources=[...new Set(s.map(x=>x.source))];return shell(`<div class="stats"><div class="stat"><span class="label">Leads</span><div class="value">${s.length}</div></div><div class="stat"><span class="label">Sources</span><div class="value">${sources.length}</div></div><div class="stat"><span class="label">Avg. score</span><div class="value">${s.length?Math.round(s.reduce((a,b)=>a+b.score,0)/s.length):0}</div></div></div><section class="panel"><h2>Audience segments</h2>${sources.map(src=>`<div class="integration"><b>${esc(src)}</b><span>${s.filter(x=>x.source===src).length} leads</span></div>`).join('')}</section>`)}
function appointmentPage(){return genericTable('Service Appointments','Agenda local de postventa',['Cliente','Vehículo','Fecha','Servicio','Estado',''],appointments.filter(a=>selected==='all'||a.client===selected).map(a=>[esc(a.customer),esc(a.model),esc(a.date),esc(a.service),tag(a.status),`<button class="tiny-btn" onclick="deleteRecord('appointments',${a.id})">Eliminar</button>`]),button('+ Nuevo turno','addAppointment()'))}
function addAppointment(){showModal('Nuevo turno postventa',`<form onsubmit="event.preventDefault();appointments.push({id:Date.now(),customer:this.elements.namedItem('customer').value,model:this.elements.namedItem('model').value,date:this.elements.namedItem('date').value,service:this.elements.namedItem('service').value,status:'Pendiente',client:this.elements.namedItem('client').value});put('appointments',appointments);closeModal();render()"><label>Cliente</label><input class="field" required name="customer"><label>Vehículo</label><input class="field" required name="model"><label>Fecha</label><input class="field" type="date" required name="date"><label>Servicio</label><input class="field" required name="service"><label>Concesionario</label><select class="field" name="client"><option value="cardys_fiat">Cardys</option><option value="overland_motors">Overland</option></select><button class="btn" style="margin-top:15px">Crear turno</button></form>`)}
function partsPage(){return shell(`<section class="panel"><h2>Parts & Accessories</h2><p class="muted">Registrar consultas de repuestos, accesorios, disponibilidad y seguimiento con responsable.</p>${button('+ Crear solicitud','newTask()')}<div class="notice">Módulo comercial en demo. No consulta inventario de repuestos.</div></section>`)}
function usersPage(){return genericTable('Users & Roles','Permisos de referencia: deben implementarse con autenticación y políticas RLS antes de producción',['Usuario','Correo','Rol','Cliente',''],people.map(u=>[esc(u.name),esc(u.email),tag(u.role),u.client==='all'?'Global':clientName(u.client),`<button class="tiny-btn" onclick="deleteRecord('users',${u.id})">Quitar</button>`]),button('+ Usuario demo','addUser()'))}
function addUser(){showModal('Usuario demo',`<form onsubmit="event.preventDefault();people.push({id:Date.now(),name:this.elements.namedItem('name').value,email:this.elements.namedItem('email').value,role:this.elements.namedItem('role').value,client:this.elements.namedItem('client').value});put('users',people);closeModal();render()"><label>Nombre</label><input class="field" name="name" required><label>Correo</label><input class="field" type="email" name="email" required><label>Rol</label><select class="field" name="role"><option>Super Admin</option><option>Dealership Admin</option><option>Sales Advisor</option><option>Post-Sales & Parts</option><option>Read Only</option></select><label>Cliente</label><select class="field" name="client"><option value="cardys_fiat">Cardys</option><option value="overland_motors">Overland</option></select><button class="btn" style="margin-top:15px">Añadir</button></form>`)}
function systemPage(){return shell(`<section class="panel"><h2>System Status</h2>${[['Demo frontend','Disponible'],['Almacenamiento del navegador','Activo local'],['Meta OAuth','No conectado'],['Supabase/Auth/RLS','No conectado'],['WhatsApp API','No conectado'],['IA generativa','No conectado']].map(x=>`<div class="integration"><b>${x[0]}</b>${tag(x[1])}</div>`).join('')}</section>`)}
function agentPage(){return shell(`<section class="panel"><h2>Customer-Facing Agent</h2><div class="notice">Sin asistente visual interno ni agente conectado. Este espacio documenta el futuro agente externo para canales de clientes.</div><div class="integration"><b>WhatsApp</b>${tag('Desactivado')}</div><div class="integration"><b>Instagram / Messenger</b>${tag('Desactivado')}</div><div class="integration"><b>TikTok / LinkedIn</b>${tag('Planificado')}</div><p class="muted">Para habilitar cualquier agente externo harán falta políticas de respuesta, consentimiento, derivación humana, logs y pruebas. Ningún envío externo se realiza desde esta demo.</p></section>`)}
function clientSettingsPage(){return shell(`<div class="campaigns">${[['Cardys · FIAT','cardys_fiat'],['Overland Motors · Jeep/RAM','overland_motors']].map(([name,id])=>`<section class="panel"><h2>${name}</h2><p class="muted">ID: ${id}</p><p class="muted">CRM · Campañas · Leads · Cotizaciones · Postventa</p><span class="tag green">Cliente piloto</span></section>`).join('')}</div>`)}
function clientsPage(){return clientSettingsPage()}
function showModal(title,body){document.getElementById('agModal')?.remove();let m=document.createElement('div');m.id='agModal';m.className='modal-backdrop';m.innerHTML=`<div class="modal-box"><div class="panel-head"><h2>${title}</h2><button class="tiny-btn" onclick="closeModal()">✕ Cerrar</button></div>${body}</div>`;m.onclick=e=>{if(e.target===m)closeModal()};document.body.appendChild(m)}
function closeModal(){document.getElementById('agModal')?.remove()}
function download(name,content,type='text/plain'){let url=URL.createObjectURL(new Blob(['\ufeff'+content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function enhancedQuote(){let tabs=[['used','Used Vehicle Quote'],['savings','Savings Plan Quote'],['factory','Factory Financing Quote']];let body=quoteType==='used'?usedQuote():financingQuote();return shell(`<div class="quote-toggle">${tabs.map(([k,t])=>`<button class="${quoteType===k?'active':''}" onclick="quoteType='${k}';render()">${t}</button>`).join('')}</div><div class="summary-grid"><section class="panel"><h2>${tabs.find(x=>x[0]===quoteType)[1]}</h2><p class="muted">Herramienta comercial para presupuestos orientativos.</p>${body}</section><section class="panel"><div class="eyebrow">ESTIMATE SUMMARY</div><div id="estimateSide" style="margin:28px 0;font-size:16px">Completá el formulario para calcular.</div><div class="notice">Toda estimación debe ser confirmada por la gerencia del concesionario.</div><h2 style="margin-top:25px">Monthly Documents</h2>${docs.slice(0,3).map(d=>`<div class="doc-card"><b>${esc(d.title)}</b><small>${esc(d.filename)}</small></div>`).join('')}${button('Ver documentos','setPage(\'documents\')')}</section></div>`)}
const qField=(label,name,value,type='text')=>`<div><label>${label}</label><input class="field" name="${name}" value="${value}" ${type==='number'?'type="number" min="0"':'type="text"'} required></div>`;
function usedQuote(){return `<form id="usedForm" onsubmit="event.preventDefault();calcUsed(this)"><div class="form-grid">${qField('Brand','brand','Fiat')}${qField('Model','model','Argo')}${qField('Trim','trim','Precision 1.8')}${qField('Year','year','2019','number')}${qField('Mileage','mileage','94000','number')}<div><label>Condition</label><select class="field" name="condition" style="width:100%"><option>Excellent</option><option selected>Good</option><option>Fair</option></select></div>${qField('Fuel type','fuel','Gasoline')}${qField('Transmission','gear','Manual')}${qField('Location','location','Buenos Aires')}${qField('Estimated market value (ARS)','market','18600000','number')}${qField('Dealer adjustment %','margin','10','number')}</div><button class="btn" style="margin-top:22px">Calculate trade-in estimate</button></form>`}
function calcUsed(f){let base=+f.market.value,margin=+f.margin.value,km=+f.mileage.value,condition=f.condition.value,adjust=condition==='Excellent'?0:condition==='Fair'?.07:.025,extraKm=km>100000?.03:0,val=Math.max(0,base*(1-margin/100-adjust-extraKm));document.getElementById('estimateSide').innerHTML=`<div class="eyebrow">ESTIMATED TRADE-IN</div><h1>${money(Math.round(val))}</h1><p class="muted">Base: ${money(base)} · margen: ${margin}% · ajuste estado: ${(adjust*100).toFixed(1)}% · ajuste kilometraje: ${(extraKm*100).toFixed(1)}%</p>`}
function financingQuote(){return `<form id="financeForm" onsubmit="event.preventDefault();calcFinance(this)"><div class="form-grid"><div><label>Client</label><select class="field" name="client" style="width:100%"><option>Cardys · Fiat</option><option>Overland Motors</option></select></div>${qField('Model','model',quoteType==='factory'?'Fiat Cronos':'Fiat Pulse')}${qField('Vehicle price (ARS)','price','30000000','number')}${qField('Down payment (ARS)','down','10000000','number')}${qField('Term (months)','months','18','number')}${qField('TNA (%)','rate','0','number')}${quoteType==='savings'?qField('Adjudication month','award','6','number'):''}</div><button class="btn" style="margin-top:22px">Calculate estimate</button></form>`}
function calcFinance(f){let p=+f.price.value,d=+f.down.value,n=+f.months.value,r=+f.rate.value/1200;if(p<=0||d>=p||n<=0){alert('Revisá precio, anticipo y plazo.');return}let financed=p-d,payment=r?financed*r/(1-Math.pow(1+r,-n)):financed/n;document.getElementById('estimateSide').innerHTML=`<div class="eyebrow">MONTHLY PAYMENT</div><h1>${money(Math.round(payment))}</h1><p class="muted">Financiado: ${money(financed)} · ${n} meses · TNA ${f.rate.value}%</p><p class="muted">${quoteType==='savings'?'La adjudicación y cuotas reales pueden variar según contrato.':'No incluye gastos ni seguros.'}</p>`}
render=function(){const funcs={dashboard:originalDashboard,leads:original.leads,pipeline:original.pipeline,inbox:original.inbox,assignment:assignmentPage,tasks:tasksPage,documents:documentsPage,quotes:enhancedQuote,recommendations:intelligence,summaries:summariesPage,opportunities:opportunitiesPage,alerts:alertsPage,campaigns:campaignIntelligence,channels:channelsPage,reports:original.reports,knowledge:knowledgePage,inventory:inventoryPage,audiences:audiencesPage,service:original.service,appointments:appointmentPage,parts:partsPage,agent:agentPage,integrations:original.integrations,users:usersPage,system:systemPage,clientsettings:clientSettingsPage,clients:clientsPage};document.getElementById('content').innerHTML=(funcs[page]||originalDashboard)();let f=document.getElementById('globalClient');if(f)f.value=selected;let topClient=document.getElementById('topClient');if(topClient)topClient.value=selected;document.getElementById('crumb').textContent=headings[page]?.[0]||'AutoGrowth OS';let rec=document.getElementById('recSelect');if(rec)rec.value=recCampaign};
newNav();render();
